/**
 * @summary List backup snapshots (newest first). Filter by kind to view daily history (14 retained) separately from manual snapshots.
 */
export const getAdminListSnapshotsUrl = (params?: AdminListSnapshotsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/backups?${stringifiedParams}`
    : `/api/admin/backups`;
};

