/**
 * @summary CSV export of content drafts (optional date range)
 */
export const getAdminExportContentDraftsCsvUrl = (
  params?: AdminExportContentDraftsCsvParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/content/drafts.csv?${stringifiedParams}`
    : `/api/admin/content/drafts.csv`;
};

